package akogen.fabric.v6;
import java.nio.file.*;import java.util.*;
public final class CharacterChecks {
 static void require(boolean v,String s){if(!v)throw new AssertionError(s);}
 static double[] bounds(Models.Model m,Models.Bone b,Expr.Context c){Models.Mat p=Models.pose(m,b,c,false,new HashMap<String,Models.Mat>(),0,0);double lo=1e9,hi=-1e9;for(float[] f:b.faces)for(int i=0;i<4;i++){double x=p.point(f[i*8],f[i*8+1],f[i*8+2])[0];lo=Math.min(lo,x);hi=Math.max(hi,x);}return new double[]{lo,hi};}
 public static void main(String[] a)throws Exception{Assets.load(Files.readAllBytes(Paths.get(a[0])));int newModels=0,shoulders=0,duos=0;for(Assets.Entry e:Assets.entries){Models.Model m=Models.load(e);Expr.Context c=new Expr.Context();c.time=2;m.activeAnimations=Models.active(m,c,false);if(e.id>=34&&e.id<=37){require(e.group.equals("Evangelion"),"Wrong new category");require(Assets.files.containsKey("assets/akogen/previews/"+e.id+".png"),"New preview absent");require(!m.bones.isEmpty(),"Empty new geometry");newModels++;}if(m.headHat){double[] body=bounds(m,m.byName.get("torso"),c),left=bounds(m,m.byName.get("left_arm"),c),right=bounds(m,m.byName.get("right_arm"),c);require(left[0]<=body[1]+.02&&right[1]>=body[0]-.02,e.name+" detached shoulder");require(left[1]>body[1]&&right[0]<body[0],e.name+" arms collapsed into body");shoulders++;}if(m.duo){for(boolean walking:new boolean[]{false,true})for(double t:new double[]{0,.5,1,2.2,4}){c.time=t;m.activeAnimations=Models.active(m,c,walking);Map<String,Models.Mat> pose=new HashMap<String,Models.Mat>();Models.Bone l=m.byName.get(m.duoFirst+"left_arm"),r=m.byName.get(m.duoSecond+"right_arm");double[] x=Models.pose(m,l,c,walking,pose,0,0).point(l.pivot[0],4.475,l.pivot[2]),y=Models.pose(m,r,c,walking,pose,0,0).point(r.pivot[0],4.475,r.pivot[2]);double d=0;for(int k=0;k<3;k++)d+=(x[k]-y[k])*(x[k]-y[k]);require(Math.sqrt(d)<1.2,e.name+" hands separate during movement");}duos++;}}require(newModels==4&&shoulders==5&&duos==2,"Incomplete character coverage");System.out.println("PASS four Evangelion additions, five attached headwear shoulder pairs, both duo hand contacts in idle and walk at five animation times");}
}
